package com.iminiapp.backend.dining.api;
import com.iminiapp.backend.dining.application.DiningManagementService;import com.iminiapp.backend.identity.web.CurrentPrincipal;import com.iminiapp.backend.shared.api.ApiResponse;import com.iminiapp.backend.shared.web.TraceIds;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.List;import static com.iminiapp.backend.dining.api.DiningModels.*;
@RestController @RequestMapping("/api/v1/admin/dining") public class AdminDiningManagementController{
 private final DiningManagementService s;public AdminDiningManagementController(DiningManagementService s){this.s=s;}
 @GetMapping("/stores") public ApiResponse<List<StoreResponse>> stores(HttpServletRequest r){return ApiResponse.success(s.stores(),TraceIds.from(r));}@PostMapping("/stores") public ApiResponse<StoreResponse> cs(@RequestBody StoreRequest b,HttpServletRequest r){return ApiResponse.success(s.saveStore(CurrentPrincipal.from(r),null,b),TraceIds.from(r));}@PutMapping("/stores/{id}") public ApiResponse<StoreResponse> us(@PathVariable long id,@RequestBody StoreRequest b,HttpServletRequest r){return ApiResponse.success(s.saveStore(CurrentPrincipal.from(r),id,b),TraceIds.from(r));}
 @GetMapping("/tables") public ApiResponse<List<TableResponse>> tables(@RequestParam(required=false)Long storeId,HttpServletRequest r){return ApiResponse.success(s.tables(storeId),TraceIds.from(r));}@PostMapping("/tables") public ApiResponse<TableResponse> ct(@RequestBody TableRequest b,HttpServletRequest r){return ApiResponse.success(s.saveTable(null,b),TraceIds.from(r));}@PutMapping("/tables/{id}") public ApiResponse<TableResponse> ut(@PathVariable long id,@RequestBody TableRequest b,HttpServletRequest r){return ApiResponse.success(s.saveTable(id,b),TraceIds.from(r));}
 @GetMapping("/categories") public ApiResponse<List<CategoryResponse>> categories(@RequestParam(required=false)Long storeId,HttpServletRequest r){return ApiResponse.success(s.categories(storeId),TraceIds.from(r));}@PostMapping("/categories") public ApiResponse<CategoryResponse> cc(@RequestBody CategoryRequest b,HttpServletRequest r){return ApiResponse.success(s.saveCategory(null,b),TraceIds.from(r));}@PutMapping("/categories/{id}") public ApiResponse<CategoryResponse> uc(@PathVariable long id,@RequestBody CategoryRequest b,HttpServletRequest r){return ApiResponse.success(s.saveCategory(id,b),TraceIds.from(r));}
 @GetMapping("/dishes") public ApiResponse<List<DishResponse>> dishes(@RequestParam(required=false)Long storeId,@RequestParam(required=false)String status,HttpServletRequest r){return ApiResponse.success(s.dishes(storeId,status),TraceIds.from(r));}@PostMapping("/dishes") public ApiResponse<DishResponse> cd(@RequestBody DishRequest b,HttpServletRequest r){return ApiResponse.success(s.saveDish(null,b),TraceIds.from(r));}@PutMapping("/dishes/{id}") public ApiResponse<DishResponse> ud(@PathVariable long id,@RequestBody DishRequest b,HttpServletRequest r){return ApiResponse.success(s.saveDish(id,b),TraceIds.from(r));}@PostMapping("/dishes/{id}/stock-adjustments") public ApiResponse<DishResponse> stock(@PathVariable long id,@RequestBody StockAdjustRequest b,HttpServletRequest r){return ApiResponse.success(s.adjustStock(id,b),TraceIds.from(r));}
 @GetMapping("/packages") public ApiResponse<List<PackageResponse>> packages(@RequestParam(required=false)Long storeId,HttpServletRequest r){return ApiResponse.success(s.packages(storeId),TraceIds.from(r));}@PostMapping("/packages") public ApiResponse<PackageResponse> cp(@RequestBody PackageRequest b,HttpServletRequest r){return ApiResponse.success(s.savePackage(null,b),TraceIds.from(r));}@PutMapping("/packages/{id}") public ApiResponse<PackageResponse> up(@PathVariable long id,@RequestBody PackageRequest b,HttpServletRequest r){return ApiResponse.success(s.savePackage(id,b),TraceIds.from(r));}
}
